def solve_preserve(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Copy

    # Find frame bounds (outermost 3s)
    frame_cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 3]

    if not frame_cells:
        return grid

    min_r = min(c[0] for c in frame_cells)
    max_r = max(c[0] for c in frame_cells)
    min_c = min(c[1] for c in frame_cells)
    max_c = max(c[1] for c in frame_cells)

    # Fill empty cells only
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if result[r][c] == 0:  # Only fill if empty
                dist_top = r - min_r
                dist_bottom = max_r - r
                dist_left = c - min_c
                dist_right = max_c - c
                layer = min(dist_top, dist_bottom, dist_left, dist_right)

                if layer % 2 == 1:
                    result[r][c] = 4
                else:
                    result[r][c] = 2

    return result

