import os, json, re
from collections import deque

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
test_in = G['Test input']

def solve_bfs(grid):
    """Fill using BFS from frame cells, layer by layer"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Get all cells with value 3 (the frame and any obstacles)
    frame_and_obstacle = set((r,c) for r in range(h) for c in range(w) if grid[r][c] == 3)

    # BFS starting from all cells touching the outer frame
    # Layer 1 = cells touching outer frame directly
    queue = deque()
    dist_map = {}

    # Add neighbors of ALL 3-cells as starting points (layer 1)
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                # Check orthogonal neighbors
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in dist_map:
                        dist_map[(nr, nc)] = 1
                        queue.append((nr, nc))

    while queue:
        r, c = queue.popleft()
        current_dist = dist_map[(r, c)]

        # Expand to neighbors
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in dist_map:
                dist_map[(nr, nc)] = current_dist + 1
                queue.append((nr, nc))

    # Fill cells with values based on their BFS distance from ANY 3-cell
    for r in range(h):
        for c in range(w):
            if result[r][c] == 0 and (r,c) in dist_map:
                layer = dist_map[(r,c)]
                if layer % 2 == 1:
                    result[r][c] = 4
                else:
                    result[r][c] = 2

    return result, dist_map

