        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
test_in = G['Test input']

def solve_bfs_inside_frame(grid):
    """Fill using BFS from frame border, but only inside frame bounds"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find frame bounds (outermost 3s)
    frame_cells = set((r,c) for r in range(h) for c in range(w) if grid[r][c] == 3)
    min_r = min(c[0] for c in frame_cells)
    max_r = max(c[0] for c in frame_cells)
    min_c = min(c[1] for c in frame_cells)
    max_c = max(c[1] for c in frame_cells)

    # Get all non-zero cells (frame + interior obstacles)
    solid = set((r,c) for r in range(min_r, max_r+1) for c in range(min_c, max_c+1) if grid[r][c] != 0)

    # BFS starting from inner neighbors of the outer frame
    queue = deque()
    dist_map = {}

    # Add empty cells adjacent to outer frame as layer 1
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if (r, c) not in solid:
                dist_map[(r, c)] = 1
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        current_dist = dist_map[(r, c)]

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in solid and (nr, nc) not in dist_map:
                dist_map[(nr, nc)] = current_dist + 1
                queue.append((nr, nc))

    # Fill based on distance
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if result[r][c] == 0 and (r,c) in dist_map:
                layer = dist_map[(r,c)]
                if layer % 2 == 1:
                    result[r][c] = 4
                else:
                    result[r][c] = 2

    return result, dist_map

