# New theory: Interior obstacles act as "anti-sources" - they create
# regions where layers are flipped or inverted relative to normal
def solve_with_obstacle_regions(grid):
    """Fill using simple layer rule, but flip values around obstacles"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find frame bounds and interior obstacles
    frame_cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    min_r = min(c[0] for c in frame_cells)
    max_r = max(c[0] for c in frame_cells)
    min_c = min(c[1] for c in frame_cells)
    max_c = max(c[1] for c in frame_cells)

    # Interior obstacles (all 3s inside frame bounds)
    interior_3s = set((r,c) for r in range(min_r+1, max_r) for c in range(min_c+1, max_c) 
                       if grid[r][c] == 3)

    print(f"Interior obstacles at: {sorted(interior_3s)}")

    # BFS to find nearest obstacle for each cell
    dist_to_obstacle = {}
    queue = deque()

    for ob in interior_3s:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = ob[0]+dr, ob[1]+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in dist_to_obstacle:
                dist_to_obstacle[(nr, nc)] = 1
                queue.append((nr, nc))

    while queue:
        r, c = queue.popleft()
        d = dist_to_obstacle[(r, c)]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in dist_to_obstacle:
                dist_to_obstacle[(nr, nc)] = d + 1
                queue.append((nr, nc))

    # Fill based on distance to OBSTACLE (closer = different value?)
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if result[r][c] == 0 and (r,c) in dist_to_obstacle:
                obs_dist = dist_to_obstacle[(r,c)]
                # Maybe closer to obstacle = inverted layer?
                frame_dist = min(r - min_r, max_r - r, c - min_c, max_c - c)

                combined = frame_dist - obs_dist  # Distance TO obstacle subtracted

                if combined % 2 == 1:
                    result[r][c] = 4
                else:
                    result[r][c] = 2

    return result

