test_in = G['Test input']

# NEW APPROACH: BFS from ALL solid cells (both frame AND interior obstacles)
# Each empty cell gets value based on shortest path to nearest solid cell
def solve_bfs_all_solid(grid):
    """Fill based on min Manhattan distance to nearest solid cell (frame OR obstacle)"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Get ALL solid cells
    solid = set((r,c) for r in range(h) for c in range(w) if grid[r][c] != 0)

    queue = deque()
    dist_map = {}

    # Start with empty cells adjacent to any solid cell
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r,c) not in dist_map:
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) in solid:
                        dist_map[(r,c)] = 1
                        queue.append((r,c))
                        break

    while queue:
        r, c = queue.popleft()
        d = dist_map[(r,c)]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in dist_map:
                dist_map[(nr, nc)] = d + 1
                queue.append((nr, nc))

    # Fill based on shortest distance to ANY solid cell
    for r in range(h):
        for c in range(w):
            if result[r][c] == 0 and (r,c) in dist_map:
                layer = dist_map[(r,c)]
                result[r][c] = 4 if layer % 2 == 1 else 2

    return result

result_demo = solve_bfs_all_solid(demo_in)
result_test = solve_bfs_all_solid(test_in)

